package com.ruoyi.web.controller.projectmanagement;
import com.ruoyi.common.core.controller.BaseController;import com.ruoyi.common.core.domain.AjaxResult;import com.ruoyi.projectmanagement.task.domain.ProjectTaskOutput;import com.ruoyi.projectmanagement.task.service.IProjectTaskService;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/projectManagement/task-output") public class ProjectTaskOutputController extends BaseController {private final IProjectTaskService service;public ProjectTaskOutputController(IProjectTaskService s){service=s;}@GetMapping("/task/{taskId}")public AjaxResult list(@PathVariable Long taskId){return success(service.outputs(taskId));}@PostMapping public AjaxResult add(@Validated @RequestBody ProjectTaskOutput o){return toAjax(service.addOutput(o,getUsername()));}@DeleteMapping("/{id}")public AjaxResult remove(@PathVariable Long id){return toAjax(service.removeOutput(id,getUsername()));}}
